  Let LAST := free_last_cells s m ch d R CHIN DPL (proj1 NN).

  (* [comment removed for export] *)
  Let BND : aceil <= lo /\ 4096 <= TH /\ TH + 4096 <= aceil /\ 6832128 <= CTX /\ CTX + 160 <= aceil
